package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class RootUniquePendingScopeTest {
 @Test public void exactlySixPhaseClaimsAndNoOverrun(){assertTrue(RootUniquePendingScope.ACTIVE);assertEquals(3,RootUniquePendingScope.MAX_PER_PHASE);assertEquals(6,RootUniquePendingScope.MAX_FRAMES);Set<String> slots=new HashSet<>();for(var p:NativeRewardCardSession.Phase.values())for(int i=1;i<=3;i++)assertTrue(slots.add(RootUniquePendingScope.slot(p,i)));assertEquals(Set.of("BEFORE_1","BEFORE_2","BEFORE_3","AFTER_1","AFTER_2","AFTER_3"),slots);for(int i:new int[]{Integer.MIN_VALUE,-1,0,4,Integer.MAX_VALUE}){assertFalse(RootUniquePendingScope.validIndex(i));assertThrows(SecurityException.class,()->RootUniquePendingScope.slot(NativeRewardCardSession.Phase.BEFORE,i));}assertThrows(SecurityException.class,()->RootUniquePendingScope.slot(null,1));}
 @Test public void halfOpenAdmissionKeepsOriginal180s(){long s=RootUniquePendingScope.STARTS_UTC,e=RootUniquePendingScope.EXPIRES_UTC;assertFalse(RootUniquePendingScope.current(s-1));assertTrue(RootUniquePendingScope.current(s));assertTrue(RootUniquePendingScope.current(e-1));assertFalse(RootUniquePendingScope.current(e));assertTrue(RootUniquePendingScope.admissionCurrent(e-180001));assertFalse(RootUniquePendingScope.admissionCurrent(e-180000));assertEquals(181000,RootUniquePendingScope.sessionDeadline(1000,s));}
 @Test public void phaseDeadlineCannotExceedParentOrUtc(){long u=RootUniquePendingScope.STARTS_UTC;assertEquals(91000,RootUniquePendingScope.deadline(1000,u,181000));assertEquals(181000,RootUniquePendingScope.deadline(101000,u+100000,181000));assertEquals(1500,RootUniquePendingScope.deadline(1000,u,1500));assertEquals(1001,RootUniquePendingScope.deadline(1000,RootUniquePendingScope.EXPIRES_UTC-1,181000));}
 @Test public void invalidClocksFailClosed(){long u=RootUniquePendingScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootUniquePendingScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootUniquePendingScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootUniquePendingScope.sessionDeadline(1,RootUniquePendingScope.EXPIRES_UTC));assertThrows(SecurityException.class,()->RootUniquePendingScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootUniquePendingScope.deadline(-1,u,100));assertThrows(SecurityException.class,()->RootUniquePendingScope.deadline(Long.MAX_VALUE,u,Long.MAX_VALUE));}
 @Test public void onlyNewNamespaceAndFixedActionSlots()throws Exception{assertEquals(15,RootUniquePendingScope.SOURCE_TASK_ID);assertNotEquals(RootUniquePendingScope.DIRECTORY,RootSelectedPendingScope.DIRECTORY);assertNotEquals(RootUniquePendingScope.DIRECTORY,RootStatusRecoveryScope.DIRECTORY);assertNotEquals(RootUniquePendingScope.DIRECTORY,RootBoundedBusinessScope.DIRECTORY);assertNotEquals(RootUniquePendingScope.DIRECTORY,RootCurrentCardScope.DIRECTORY);assertNotEquals(RootUniquePendingScope.DIRECTORY,RootImageSeriesScope.DIRECTORY);assertNotEquals(RootUniquePendingScope.DIRECTORY,RootFamilyDiagnosticProfile.DIRECTORY);assertNotEquals(RootUniquePendingScope.DIRECTORY,AutonomousRewardCardScope.DIRECTORY);assertNotEquals(RootUniquePendingScope.DIRECTORY,RootCaptureScope.PREFLIGHT_DIRECTORY);assertThrows(SecurityException.class,()->RootUniquePendingScope.store(null,NativeRewardCardSession.Phase.BEFORE,1));assertThrows(SecurityException.class,()->RootUniquePendingScope.burnAction(Path.of("unused"),"BEFORE","safe"));assertThrows(SecurityException.class,()->RootUniquePendingScope.burnAction(Path.of("unused"),"../TAP","safe"));assertThrows(SecurityException.class,()->RootUniquePendingScope.burnAction(null,"TAP","safe"));}
 @Test public void badClaimsAndOversizedMetadataNeverWrite()throws Exception{var store=RootUniquePendingScope.store(Path.of("unused"),NativeRewardCardSession.Phase.BEFORE,1);assertThrows(SecurityException.class,()->store.burn("invalid","safe"));assertThrows(SecurityException.class,()->store.burn("11111111-1111-1111-1111-111111111111",null));assertThrows(SecurityException.class,()->store.burn("11111111-1111-1111-1111-111111111111","x".repeat(2049)));assertThrows(SecurityException.class,()->RootUniquePendingScope.burnAction(Path.of("unused"),"RETURN",null));}
 @Test public void durablePrimitiveHasNoRecoveryOrTruncate()throws Exception{Path p=Path.of("../app/src/main/java/com/aliothmoon/maafw/once/RootUniquePendingScope.java");if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once/RootUniquePendingScope.java");String s=Files.readString(p);assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("c.force(true)"));assertFalse(s.contains("delete("));assertFalse(s.contains("TRUNCATE_EXISTING"));assertTrue(s.contains("maxFrames=6 maxPerPhase=3 maxTap=1 maxReturn=1"));}
}
